<?php
namespace App\Livewire\Landlord\Maintenance; use App\Livewire\Concerns\InteractsWithAuthenticatedUser; use App\Livewire\Concerns\InteractsWithRoleShells; use App\Models\MaintenanceRequest; use App\Models\MaintenanceRequestPhoto; use App\Support\WorkflowNotifier; use Illuminate\View\View; use Livewire\Component; use Livewire\WithFileUploads;
class Show extends Component {use InteractsWithAuthenticatedUser,InteractsWithRoleShells,WithFileUploads; public MaintenanceRequest $request; public ?string $note=null; public mixed $photo=null; public function mount(MaintenanceRequest $request):void{abort_unless($request->landlord_id===$this->currentUserId(),404);$this->request=$request->load(['property','tenant','events','photos']);} public function addUpdate():void{$this->validate(['note'=>['required','string','max:1000']]);$this->request->events()->create(['actor_id'=>$this->currentUserId(),'event_type'=>'landlord_update','note'=>$this->note]);$this->note=null;$this->reload();} public function addPhoto():void{$this->validate(['photo'=>['required','image','mimes:jpg,jpeg,png,webp','max:5120']]);abort_if($this->request->photos()->count()>=20,422);$p=$this->photo->store('maintenance-requests/'.$this->request->id.'/landlord','local');MaintenanceRequestPhoto::create(['maintenance_request_id'=>$this->request->id,'uploaded_by_id'=>$this->currentUserId(),'source'=>'landlord','file_path'=>$p,'original_name'=>$this->photo->getClientOriginalName(),'file_size'=>$this->photo->getSize()]);$this->reset('photo');$this->reload();} public function updateStatus(string $to):void{abort_unless(in_array([$this->request->status,$to],[['submitted','acknowledged'],['acknowledged','in_progress'],['in_progress','resolved']],true),422);$field=['acknowledged'=>'acknowledged_at','in_progress'=>'started_at','resolved'=>'resolved_at'][$to];$this->request->update(['status'=>$to,$field=>now()]);$this->request->events()->create(['actor_id'=>$this->currentUserId(),'event_type'=>$to,'note'=>$this->note]);$titles=['acknowledged'=>'Your maintenance request has been acknowledged.','in_progress'=>'Work on your maintenance request is in progress.','resolved'=>'Your landlord marked the maintenance request as resolved.'];app(WorkflowNotifier::class)->notify($this->request->tenant,'maintenance-'.$to.':'.$this->request->id,$titles[$to],$this->request->title,route('tenant.maintenance.show',$this->request),'maintenance','View request');$this->note=null;$this->reload();} private function reload():void{$this->request->refresh()->load(['property','tenant','events','photos']);} public function render():View{return view('livewire.landlord.maintenance.show')->layout('layouts.dashboard-shell',$this->landlordShell('Maintenance Request'));}}
